import {createServer} from 'vite';
import vue from '@vitejs/plugin-vue';
const entry=`import {createApp,ref} from 'vue';import ElementPlus from 'element-plus';import 'element-plus/dist/index.css';import '/frontend/admin/styles/index.css';import ProductImagePreview from '/frontend/admin/components/ProductImagePreview.vue';import {apiClient,setAuthToken,currentApiCacheScope} from '/frontend/admin/utils/api.js';
localStorage.setItem('baodanAuthUser',JSON.stringify({id:1,tenant:{id:2,slug:'a'}}));setAuthToken('image-test');currentApiCacheScope();window.imageErrors=[];
const app=createApp({components:{ProductImagePreview},setup(){const rows=ref(Array.from({length:8},(_,i)=>({id:101+i,name:'库存图片 '+(101+i)}))),selected=ref([]),page=ref(1);return{rows,selected,page,refresh(){rows.value=rows.value.map(r=>({...r}));},flip(){page.value=page.value===1?2:1;rows.value=Array.from({length:8},(_,i)=>({id:page.value===1?101+i:201+i,name:'库存图片 '+(page.value===1?101+i:201+i)}));},async edit(){await apiClient.put('/api/products/102',{image_url:'changed'});},switchTenant(){localStorage.setItem('baodanAuthUser',JSON.stringify({id:8,tenant:{id:3,slug:'b'}}));setAuthToken('other-scope');currentApiCacheScope();}};},template:'<section><div class="image-test-toolbar"><el-button @click="refresh">批量刷新列表</el-button><el-button @click="flip">切换页码</el-button><el-button @click="edit">更新第2张图</el-button><el-button @click="switchTenant">切换企业</el-button><span>已选 {{selected.length}} 项</span></div><el-table :data="rows" row-key="id" @selection-change="value=>selected=value"><el-table-column type="selection" reserve-selection/><el-table-column label="库存" prop="name"/><el-table-column label="图片" width="150"><template #default="{row}"><ProductImagePreview :src="\x60/api/products/\x24{row.id}/image?thumb=1\x60" :preview-list="[\x60/api/products/\x24{row.id}/image\x60]" :load-delay="20" size="portrait"/></template></el-table-column><el-table-column label="数量"><template #default="{row}"><el-input-number :model-value="1" :min="0"/></template></el-table-column></el-table></section>'});app.use(ElementPlus);app.config.errorHandler=error=>window.imageErrors.push(error.message);app.mount('#app');`;
export async function startProductImagePreview(){
 const calls=[],active={value:0,peak:0};let fail=true,version=1;
 const cacheDir='/tmp/ozon-image-preview-vite';
 const server=await createServer({configFile:false,resolve:{alias:[{find:/^vue$/,replacement:'vue/dist/vue.esm-bundler.js'}]},root:process.cwd(),publicDir:false,cacheDir,optimizeDeps:{noDiscovery:true,include:['vue','element-plus']},logLevel:'error',server:{host:'127.0.0.1',port:8788,strictPort:true},plugins:[vue(),{name:'image-preview-fixture',resolveId(id){if(id==='/__image-test.js')return id;},load(id){if(id==='/__image-test.js')return entry;},configureServer(server){server.middlewares.use((req,res,next)=>{
  const url=new URL(req.url,'http://localhost');
  if(url.pathname==='/'){res.setHeader('Content-Type','text/html');return res.end('<html><body><div id="app"></div><script type="module" src="/__image-test.js"></script></body></html>');}
  if(req.method==='PUT'&&url.pathname==='/api/products/102'){version++;res.setHeader('Content-Type','application/json');return res.end('{"ok":true}');}
  const image=url.pathname.match(/^\/api\/products\/(\d+)\/image$/);if(!image)return next();
  const id=Number(image[1]),scope=req.headers.authorization||url.searchParams.get('token');calls.push({id,scope,thumb:url.searchParams.get('thumb'),version});active.value++;active.peak=Math.max(active.peak,active.value);
  setTimeout(()=>{active.value--;if(res.destroyed)return;if(id===103&&fail){fail=false;res.statusCode=502;res.setHeader('Content-Type','application/json');return res.end('{"error":"one image unavailable"}');}
   res.setHeader('Content-Type','image/svg+xml');res.setHeader('Cache-Control','no-store');res.end('<svg xmlns="http://www.w3.org/2000/svg" width="64" height="84"><rect width="64" height="84" fill="'+(scope==='Bearer other-scope'?'blue':version>1&&id===102?'red':'green')+'"/></svg>');
  },id===107?2000:60);
 });}}]});await server.listen();return{server,calls,active};
}
